import{_ as o,o as i,c as t,a2 as e}from"./chunks/framework.BXA5Pi9t.js";const p=JSON.parse('{"title":"CephFS Code Walkthrough: MDSMonitoring","description":"","frontmatter":{"title":"CephFS Code Walkthrough: MDSMonitoring","date":"2021-05-03T00:00:00.000Z","updated":"2021-05-04T00:00:00.000Z","tags":["CephFS","MDS Monitoring","Paxos","Distributed Storage","Ceph Architecture"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2021/CephFS_Code_Walkthrough_-_MDSMonitoring.md","filePath":"posts/2021/CephFS_Code_Walkthrough_-_MDSMonitoring.md","lastUpdated":1780459816000}'),l={name:"posts/2021/CephFS_Code_Walkthrough_-_MDSMonitoring.md"};function r(n,a,h,s,M,d){return i(),t("div",null,[...a[0]||(a[0]=[e('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><h4 id="会议主题-mds-monitor-的深入探讨" tabindex="-1">会议主题：MDS Monitor 的深入探讨 <a class="header-anchor" href="#会议主题-mds-monitor-的深入探讨" aria-label="Permalink to &quot;会议主题：MDS Monitor 的深入探讨&quot;">​</a></h4><h4 id="会议时间-具体时间" tabindex="-1">会议时间：[具体时间] <a class="header-anchor" href="#会议时间-具体时间" aria-label="Permalink to &quot;会议时间：[具体时间]&quot;">​</a></h4><h4 id="参会人员-参会人员名单" tabindex="-1">参会人员：[参会人员名单] <a class="header-anchor" href="#参会人员-参会人员名单" aria-label="Permalink to &quot;参会人员：[参会人员名单]&quot;">​</a></h4><h4 id="会议内容总结" tabindex="-1">会议内容总结： <a class="header-anchor" href="#会议内容总结" aria-label="Permalink to &quot;会议内容总结：&quot;">​</a></h4><ol><li><p><strong>MDS Monitor 概述</strong></p><ul><li>MDS Monitor 是 Ceph 分布式存储系统中 Paxos 服务的一部分，负责管理和监控 MDS（Metadata Server）集群的状态。</li><li>功能包括：通过修改 FS Map 或 MDS Map 驱动集群状态变化，分发变化给客户端和 MDS；监控 MDS 健康状态，标记延迟的 MDS 并进行替换；提供命令接口，如创建新文件系统或失败 MDS。</li></ul></li><li><p><strong>MDS Monitor 的组件和操作</strong></p><ul><li>MDS Monitor 管理多个 FS Map，每个 FS Map 包含一个或多个 MDS Map。</li><li>提供命令行接口，如创建新文件系统或失败 MDS。</li><li>MDS 定期向 Monitor 发送 MDS Beacon 消息，Monitor 根据这些消息驱动 MDS 状态的变化。</li></ul></li><li><p><strong>代码实现细节</strong></p><ul><li>引入 Paxos FS Map 类来保护当前和待处理的 FS Map，防止意外修改。</li><li>处理 MDS 发送的 Beacon 消息，确保 MDS 不会因 Monitor 负载过高而被错误标记为延迟。</li><li>处理如 <code>mds fail</code> 或 <code>fs new</code> 等命令，修改 FS Map。</li></ul></li><li><p><strong>历史和改进</strong></p><ul><li>自 2018 年引入 Paxos FS Map 和增量控制激活，提高了系统的稳定性和可管理性。</li><li>2019 年增加 standby replay 功能，简化了配置。</li><li>2020 年增加 MDS 亲和性设置，使 MDS 可以更灵活地服务于特定文件系统。</li></ul></li></ol><h4 id="决定事项" tabindex="-1">决定事项： <a class="header-anchor" href="#决定事项" aria-label="Permalink to &quot;决定事项：&quot;">​</a></h4><ul><li>确认了 MDS Monitor 的主要功能和操作流程。</li><li>讨论了 MDS Monitor 的代码实现细节，特别是 Paxos FS Map 和 Beacon 处理机制。</li></ul><h4 id="后续行动计划" tabindex="-1">后续行动计划： <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划：&quot;">​</a></h4><ul><li>继续优化 MDS Monitor 的代码，特别是处理 Beacon 消息的逻辑。</li><li>探索进一步的功能增强，如改进订阅机制，减少 Monitor 的通信负载。</li></ul><h4 id="会议结束语" tabindex="-1">会议结束语： <a class="header-anchor" href="#会议结束语" aria-label="Permalink to &quot;会议结束语：&quot;">​</a></h4><ul><li>感谢所有参会人员的积极参与和 Patrick 的详细讲解。</li><li>期待明天的进一步讨论和改进。</li></ul><p><strong>备注</strong>：本会议纪要基于会议内容的总结，具体的技术细节和代码实现可能需要参考相关的技术文档和代码库。</p>',13)])])}const u=o(l,[["render",r]]);export{p as __pageData,u as default};
